using System.Text.Json;
using ChartForgeX.Mermaid;
using ChartForgeX.Themes;
using ChartForgeX.VisualArtifacts;
using Microsoft.Playwright;
using Xunit;
namespace ChartForgeX.Tests;
public sealed partial class MermaidNotationReferenceRenderingTests {
    [MermaidReferenceTheory] [Trait("Category","MermaidReference")]
    [InlineData(false,390)] [InlineData(true,390)] [InlineData(false,1100)] [InlineData(true,1100)]
    public async Task PinnedPresetsRetainTheirSourcePaletteIndexAndNeoHeaderDatumWithoutClaimingWholePixelIdentity(bool dark,int width) {
        var corpus=Path.Combine(TestRepository.Root,"tests","mermaid-conformance");using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(corpus,"compatibility.json")));var reference=manifest.RootElement.GetProperty("references").GetProperty("12");var bundle=Path.Combine(corpus,"node_modules",reference.GetProperty("package").GetString()!);using var installed=JsonDocument.Parse(File.ReadAllText(Path.Combine(bundle,"package.json")));Assert.Equal(reference.GetProperty("version").GetString(),installed.RootElement.GetProperty("version").GetString());var source=SequencePresetSourceFixture.Canonical();var result=MermaidRenderer.Render(source,new MermaidRenderOptions{Presentation=new MermaidPresentationOptions{ThemeMode=dark?VisualThemeMode.Dark:VisualThemeMode.Light,FontFamily=BrowserProofFonts.Family},Sequence=new MermaidSequenceRenderOptions{Width=width-32,Height=860}});Assert.False(result.HasErrors);var artifact=result.Artifact!;var svg=artifact.ToSvg();var png=artifact.ToPng();var html="<style>body{margin:0;padding:16px;box-sizing:border-box}section{max-width:100%;overflow:auto;margin-bottom:24px}svg,img{display:block;max-width:none}</style><section id='reference'></section><section id='native'>"+svg+"</section><section><img id='png' src='data:image/png;base64,"+Convert.ToBase64String(png)+"'></section>";await using var session=await BrowserProofFonts.OpenAsync(html,width,1100);await session.Page.AddScriptTagAsync(new PageAddScriptTagOptions{Path=Path.Combine(bundle,"dist","mermaid.min.js")});var observed=await ObserveAsync(session.Page,source,"",dark,new Dictionary<string,int>{{"sequence-participant",2}},dark?"redux-dark-color":"redux-color","neo");var roles=await session.Page.EvaluateReferenceJsonAsync("""
            () => Object.fromEntries(['reference','native'].map(id=>{const s=document.querySelector('#'+id+' svg'),native=id==='native';const groups=[...s.querySelectorAll(native?'[data-cfx-role="sequence-participant"]':'g[data-et="participant"]')];return [id,{heads:groups.map(g=>({id:g.getAttribute(native?'data-cfx-source-id':'data-id'),labelBottom:Math.max(...[...g.querySelectorAll('text')].flatMap(t=>{const spans=[...t.querySelectorAll('tspan')];return (spans.length?spans:[t]).filter(e=>e.textContent.trim()).map(e=>e.getBoundingClientRect().bottom)})),strokes:[g,...g.querySelectorAll('*')].map(e=>getComputedStyle(e).stroke),fills:[g,...g.querySelectorAll('*')].map(e=>getComputedStyle(e).fill)})),text:[...s.querySelectorAll('text')].map(t=>({text:t.textContent,rect:{bottom:t.getBoundingClientRect().bottom}}))}]}))
            """);var stem="sequence-preset-reference12-"+width+(dark?"-dark":"-light");await CaptureAsync(session.Page,stem,svg,png,artifact.ToInterchangeJson(),observed);if(Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY") is {Length:>0} output)File.WriteAllText(Path.Combine(output,stem+".roles.json"),roles.GetRawText());foreach(var surface in new[]{"reference","native"}){var heads=roles.GetProperty(surface).GetProperty("heads");Assert.Equal(new[]{"A","B"},heads.EnumerateArray().Select(x=>x.GetProperty("id").GetString()));Assert.Equal(surface=="native"?0:1.5,heads[1].GetProperty("labelBottom").GetDouble()-heads[0].GetProperty("labelBottom").GetDouble(),2);Assert.Contains(heads[0].GetProperty("strokes").EnumerateArray(),e=>e.GetString()=="rgb(232, 121, 249)");Assert.Contains(heads[1].GetProperty("strokes").EnumerateArray(),e=>e.GetString()=="rgb(45, 212, 191)");foreach(var word in new[]{"Review","Owner","Archive","Save","Stored","Audit"})Assert.Contains(word,observed.GetProperty(surface+"Text").GetString());}Assert.Empty(observed.GetProperty("clip").EnumerateArray());Assert.Equal(0,observed.GetProperty("nativeScripts").GetInt32());InteractiveChartBrowser.AssertNoConsoleErrors(session);
    }
    [MermaidReferenceTheory] [Trait("Category","MermaidReference")] [InlineData(390)] [InlineData(1100)]
    public async Task TrulyOmittedInitializeAndSourceAppearanceUsesSequenceDefaultsInsteadOfGlobalDefaults(int width) {
        var corpus=Path.Combine(TestRepository.Root,"tests","mermaid-conformance");using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(corpus,"compatibility.json")));var reference=manifest.RootElement.GetProperty("references").GetProperty("12");var bundle=Path.Combine(corpus,"node_modules",reference.GetProperty("package").GetString()!);using var installed=JsonDocument.Parse(File.ReadAllText(Path.Combine(bundle,"package.json")));Assert.Equal(reference.GetProperty("version").GetString(),installed.RootElement.GetProperty("version").GetString());var source=SequencePresetSourceFixture.Canonical();var result=MermaidRenderer.Render(source,new MermaidRenderOptions{Presentation=new MermaidPresentationOptions{FontFamily=BrowserProofFonts.Family},Sequence=new MermaidSequenceRenderOptions{Width=width-32,Height=860}});Assert.False(result.HasErrors);Assert.Empty(result.Document!.Configuration.Settings);var artifact=result.Artifact!;var svg=artifact.ToSvg();var png=artifact.ToPng();var html="<style>body{margin:0;padding:16px;box-sizing:border-box}section{max-width:100%;overflow:auto;margin-bottom:24px}svg,img{display:block;max-width:none}</style><section id='reference'></section><section id='native'>"+svg+"</section><section><img id='png' src='data:image/png;base64,"+Convert.ToBase64String(png)+"'></section>";await using var session=await BrowserProofFonts.OpenAsync(html,width,1100);await session.Page.AddScriptTagAsync(new PageAddScriptTagOptions{Path=Path.Combine(bundle,"dist","mermaid.min.js")});var observed=await ObserveAsync(session.Page,source,"",false,new Dictionary<string,int>{{"sequence-participant",2}},omitAppearance:true);var actual=await session.Page.EvaluateReferenceJsonAsync("""
            () => Object.fromEntries(['reference','native'].map(id=>{const s=document.querySelector('#'+id+' svg'),native=id==='native';const g=s.querySelector(native?'[data-cfx-role="sequence-participant"]':'g[data-et="participant"]');const tab=s.querySelector(native?'[data-cfx-role="sequence-fragment-tab"]':'.labelBox');return [id,{fills:[g,...g.querySelectorAll('*')].map(e=>getComputedStyle(e).fill),tabHeight:tab.getBBox().height,hasNeoBand:native?s.querySelectorAll('[data-cfx-role="sequence-participant-glyph"]').length>0:!!s.querySelector('.actor-bottom')}]}))
            """);var stem="sequence-preset-true-omitted-reference12-"+width;await CaptureAsync(session.Page,stem,svg,png,artifact.ToInterchangeJson(),observed);if(Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY") is {Length:>0} output)File.WriteAllText(Path.Combine(output,stem+".roles.json"),actual.GetRawText());foreach(var surface in new[]{"reference","native"}){Assert.Contains(actual.GetProperty(surface).GetProperty("fills").EnumerateArray(),e=>e.GetString()=="rgb(253, 244, 255)");Assert.Equal(35,actual.GetProperty(surface).GetProperty("tabHeight").GetDouble(),6);Assert.True(actual.GetProperty(surface).GetProperty("hasNeoBand").GetBoolean());}Assert.Equal("omitted",observed.GetProperty("referenceLook").GetString());Assert.Empty(observed.GetProperty("clip").EnumerateArray());InteractiveChartBrowser.AssertNoConsoleErrors(session);
    }

}
